changeSet.sql:
INSERT INTO pep_category (country_iso, code, label, kind, risk_class, sort_order, legal_reference)
VALUES ('PL', 'PL-EU', 'Polonaiss exerçant une fonction européenne', 'EU', 1, 10, 'Liste de la Commission, JO C/2023/724');

INSERT INTO pep_function (category_id, label, institution, expected_holders)
SELECT c.id, f.label, f.institution, f.expected_holders
FROM pep_category c JOIN (
    SELECT 'PL-EU' AS code, 'Député européen élu en Pologne' AS label, 'Parlement européen' AS institution, 53 AS expected_holders
    UNION ALL SELECT 'PL-EU', 'Membre polonais de la Commission européenne', 'Commission européenne', 1
) f ON f.code = c.code;

